package org.example.ui;
import org.example.dao.UserDao; import org.example.dao.TaskDao; import org.example.model.User; import java.sql.SQLException; import java.util.Scanner;
public class Authentication { private final Scanner scanner; private final UserDao userDao; private final TaskDao taskDao=new TaskDao(); public Authentication(Scanner scanner,UserDao userDao){this.scanner=scanner;this.userDao=userDao;}
 public void start(){boolean running=true;while(running){System.out.println("\n========== TASKPILOT ==========");System.out.println("Company Task Assignment and Progress Monitoring System");System.out.println("1. Login\n2. Register Account\n0. Exit");System.out.print("Choose: ");switch(scanner.nextLine().trim()){case "1"->login();case "2"->register();case "0"->{running=false;System.out.println("Goodbye!");}default->System.out.println("Invalid choice.");}}}
 private void login(){try{System.out.print("Username: ");String username=scanner.nextLine();System.out.print("Password: ");String password=scanner.nextLine();User user=userDao.login(username,password);if(user==null){System.out.println("Invalid username or password.");return;}if(!"APPROVED".equalsIgnoreCase(user.status())){System.out.println("Account is PENDING. Please wait for admin approval.");return;}switch(user.roles().toUpperCase()){case "ADMIN"->new AdminMenu(scanner,userDao,user,taskDao).start();case "MANAGER"->new ManagerMenu(scanner,user,userDao,taskDao).start();case "EMPLOYEE"->new EmployeeMenu(scanner,user,taskDao).start();default->System.out.println("Unknown account role.");}}catch(SQLException e){System.out.println("Login failed: "+e.getMessage());}}
 private void register(){try{System.out.print("Choose username: ");String username=scanner.nextLine().trim();if(username.isEmpty()){System.out.println("Username cannot be empty.");return;}System.out.print("Choose password: ");String password=scanner.nextLine();if(password.isBlank()){System.out.println("Password cannot be empty.");return;}System.out.println("Register as: 1. MANAGER  2. EMPLOYEE");System.out.print("Choose role: ");String role=switch(scanner.nextLine().trim()){case "1"->"MANAGER";case "2"->"EMPLOYEE";default->null;};if(role==null){System.out.println("Invalid role.");return;}if(userDao.register(username,password,role))System.out.println("Registration submitted. Status: PENDING. An admin must approve it.");}catch(SQLException e){System.out.println("Registration failed. Username may already exist.");}}
}
